mapper.select:
SELECT s.tenant_id,s.source_id,sv.source_version,s.owner_project_id,s.ownership,s.title,s.classification, sv.media_type,sv.size_bytes,sv.rights_revision,r.status AS rights_status,o.folder_id, COALESCE(f.category,o.category) AS category, COALESCE(o.labels,JSON_ARRAY()) AS labels,o.revision AS organization_revision, EXISTS(SELECT 1 FROM user_source_bookmark ub WHERE ub.user_id=#{userId} AND ub.source_version=sv.source_version) AS bookmarked, CASE WHEN SUM(p.parse_status='COMPLETE') > 0 THEN 'COMPLETE' WHEN SUM(p.parse_status='PROCESSING') > 0 THEN 'PROCESSING' WHEN SUM(p.parse_status='QUEUED') > 0 THEN 'QUEUED' WHEN SUM(p.parse_status='PARTIAL_FAILED') > 0 THEN 'PARTIAL_FAILED' WHEN SUM(p.parse_status='FAILED') > 0 THEN 'FAILED' ELSE NULL END AS processing_status, CASE WHEN SUM(g.approval_status='APPROVED') > 0 THEN 'APPROVED' WHEN SUM(g.approval_status='PENDING') > 0 THEN 'PENDING' WHEN SUM(g.approval_status='DISABLED') > 0 THEN 'DISABLED' ELSE NULL END AS approval_status, CASE WHEN SUM(g.lifecycle='ACTIVE') > 0 THEN 'ACTIVE' WHEN SUM(g.lifecycle='RECYCLED') > 0 THEN 'RECYCLED' WHEN SUM(g.lifecycle='PURGE_PENDING') > 0 THEN 'PURGE_PENDING' WHEN SUM(g.lifecycle='PURGED') > 0 THEN 'PURGED' ELSE NULL END AS lifecycle, sv.created_at FROM source_version sv JOIN source s ON s.tenant_id=sv.tenant_id AND s.source_id=sv.source_id JOIN rights_revision r ON r.tenant_id=sv.tenant_id AND r.rights_revision=sv.rights_revision LEFT JOIN source_organization o ON o.tenant_id=s.tenant_id AND o.source_id=s.source_id LEFT JOIN source_folder f ON f.tenant_id=o.tenant_id AND f.folder_id=o.folder_id LEFT JOIN parse_version p ON p.tenant_id=sv.tenant_id AND p.source_version=sv.source_version LEFT JOIN source_use_gate g ON g.tenant_id=p.tenant_id AND g.source_version=p.source_version AND g.parse_version=p.parse_version WHERE 1=1 AND (s.owner_project_id IS NULL OR s.owner_project_id=#{projectId}) AND s.ownership=#{ownership} AND COALESCE(f.category,o.category)=#{category} AND JSON_SEARCH(COALESCE(o.labels,JSON_ARRAY()),'one',#{tag}) IS NOT NULL AND o.folder_id=#{folderId} AND EXISTS (SELECT 1 FROM collection_member cm WHERE cm.source_version=sv.source_version AND cm.collection_version=#{collectionVersion}) GROUP BY s.tenant_id,s.source_id,sv.source_version,s.owner_project_id,s.ownership,s.title,s.classification, sv.media_type,sv.size_bytes,sv.rights_revision,r.status,o.folder_id,COALESCE(f.category,o.category),o.labels,o.revision,sv.created_at
AND approval_status=#{approvalStatus} AND lifecycle=#{lifecycle} AND bookmarked=#{bookmarked}
ORDER BY sv.source_version

SELECT a.tenant_id,a.project_id,a.artifact_id,a.run_id,a.document_revision,a.artifact_kind,a.sha256,
  a.size_bytes,a.media_type,a.created_at,a.classification
FROM artifact a WHERE 1=1
  AND a.project_id=#{projectId}
  AND a.artifact_kind=#{artifactKind}
ORDER BY a.artifact_id

SELECT c.source_version,c.parse_version,c.chunk_id,c.ordinal,c.node_id,n.node_kind,c.locator,n.content_ref,
  n.node_hash,c.quote_hash,c.raw_text
FROM source_chunk c
JOIN content_node n ON n.tenant_id=c.tenant_id AND n.source_version=c.source_version
  AND n.parse_version=c.parse_version AND n.node_id=c.node_id
WHERE c.source_version=#{sourceVersion} AND c.parse_version=#{parseVersion}

  AND c.chunk_id=#{chunkId}
  AND c.ordinal>#{afterOrdinal}

ORDER BY c.ordinal,c.chunk_id
LIMIT #{fetchLimit}

SELECT user_id,source_version,last_read_at,locator,schema_version,schema_manifest_sha256,revision
FROM source_read_history WHERE user_id=#{userId} AND source_version=#{sourceVersion}
FOR UPDATE

SELECT u.* FROM () u
WHERE 1=1
  AND u.project_id=#{projectId}
  AND u.usage_kind=#{usageKind}
  AND u.usage_key>#{after}
ORDER BY u.usage_key
LIMIT #{fetchLimit}

SELECT COUNT(*) FROM () u
WHERE 1=1
  AND u.project_id=#{projectId}
  AND u.usage_kind=#{usageKind}

SELECT policy_revision,category,retention_duration,start_event,hold_override,approver_id,effective_from,
  purge_method,backup_expiry,status,revision
FROM retention_policy_revision WHERE policy_revision=#{policyRevision}

SELECT source_version,decision_id,decision,from_status,to_status,reason,policy_revision,deletion_id,
  actor_id,decided_at,expected_revision,resulting_revision,schema_manifest_sha256
FROM source_lifecycle_decision WHERE decision_id=#{decisionId}

SELECT deletion_id,target_version,policy_revision,status,revision,updated_at
FROM deletion_job WHERE target_version=#{sourceVersion}
ORDER BY updated_at DESC,deletion_id DESC LIMIT 1

mapper.update:
UPDATE source_use_gate SET approval_revision=#{approvalRevision},approval_status=#{approvalStatus},revision=#{resultingRevision}
WHERE source_version=#{sourceVersion} AND parse_version=#{parseVersion} AND revision=#{expectedRevision}
  AND lifecycle='ACTIVE' AND upload_status='RECEIVED'

UPDATE source_read_history SET last_read_at=#{now},locator=#{locator},schema_version='1.0.0',
  schema_manifest_sha256=#{schemaManifest},classification=#{classification},revision=#{resultingRevision},updated_at=#{now}
WHERE user_id=#{userId} AND source_version=#{sourceVersion} AND revision=#{expectedRevision}

UPDATE source_lifecycle_state SET status=#{toStatus},last_decision_id=#{decisionId},
  revision=#{resultingRevision},updated_at=#{now}
WHERE source_version=#{sourceVersion} AND status=#{fromStatus} AND revision=#{expectedRevision}

UPDATE source_folder SET
  name=CASE WHEN #{decision}='RENAME' THEN #{name} ELSE name END,
  parent_id=CASE WHEN #{decision}='MOVE' THEN #{parentId} ELSE parent_id END,
  revision=revision+1,updated_at=#{now}
WHERE folder_id=#{folderId} AND revision=#{expectedRevision}

UPDATE source_organization SET
  folder_id=CASE WHEN #{decision}='MOVE' THEN #{folderId} ELSE folder_id END,
  labels=CASE WHEN #{decision}='LABEL' THEN #{labels} ELSE labels END,
  maintainer_id=#{userId},schema_version='1.0.0',schema_manifest_sha256=#{schemaManifest},
  revision=revision+1,updated_at=#{now}
WHERE source_id=#{sourceId} AND revision=#{expectedRevision}

UPDATE deletion_item SET status='CONFIRMED',receipt_ref=#{receiptRef},lease_owner=NULL,lease_expires_at=NULL,
  revision=revision+1,updated_at=#{now}
WHERE item_id=#{itemId} AND deletion_id=#{deletionId} AND status IN ('QUEUED','RUNNING') AND revision=#{expectedRevision}
